param(
    [switch]$Force
)

$ErrorActionPreference = "Stop"

if (-not (Test-Path ".git")) {
    throw "Run this script from the root of the bursar-cashbook Git repository."
}

if (-not (Test-Path "app/main.py")) {
    throw "app/main.py was not found. Run this from the bursar-cashbook repository root."
}

$status = git status --porcelain
if ($status -and -not $Force) {
    Write-Host "Your working tree has uncommitted changes:" -ForegroundColor Yellow
    git status --short
    throw "Commit/stash those changes first, or rerun with -Force."
}

$expectedCommit = "f139045ef3dbb264f6327068cb96a6fc803ed6b2"
$currentCommit = (git rev-parse HEAD).Trim()
if ($currentCommit -ne $expectedCommit) {
    Write-Host "Warning: this patch was prepared from commit $expectedCommit." -ForegroundColor Yellow
    Write-Host "Current HEAD is $currentCommit." -ForegroundColor Yellow
    if (-not $Force) {
        throw "Checkout the audited commit/master first, or rerun with -Force if you intentionally want the overlay."
    }
}

$timestamp = Get-Date -Format "yyyyMMdd-HHmmss"
if (Test-Path "cashbook.db") {
    $backup = "cashbook.pre-phase1-$timestamp.db"
    Copy-Item "cashbook.db" $backup
    Write-Host "Backed up existing SQLite DB to $backup" -ForegroundColor Cyan
}

$tempRoot = Join-Path ([System.IO.Path]::GetTempPath()) "bursar-phase1-$([guid]::NewGuid())"
$tempZip = "$tempRoot.zip"
New-Item -ItemType Directory -Path $tempRoot | Out-Null

