'@ -replace "`r|`n", ""

[System.IO.File]::WriteAllBytes($tempZip, [Convert]::FromBase64String($payload))
Expand-Archive -Path $tempZip -DestinationPath $tempRoot -Force

$source = Join-Path $tempRoot "bursar-cashbook-phase1"
$files = @(
    ".gitignore",
    "README.md",
    "requirements.txt",
    "seed.py",
    "app/__init__.py",
    "app/bank_parser.py",
    "app/categorize.py",
    "app/db.py",
    "app/fingerprints.py",
    "app/main.py",
    "app/models.py",
    "app/reconciliation.py",
    "app/static/review.html",
    "app/wced_export.py",
    "tests/__init__.py",
    "tests/test_bank_parser.py",
    "tests/test_categorize.py",
    "tests/test_main.py",
    "tests/test_models.py",
    "tests/test_reconciliation.py",
    "tests/test_seed.py",
    "tests/test_wced_export.py"
)

foreach ($relative in $files) {
    $src = Join-Path $source $relative
    $dst = Join-Path (Get-Location) $relative
    $dstDir = Split-Path -Parent $dst
    if ($dstDir -and -not (Test-Path $dstDir)) {
        New-Item -ItemType Directory -Path $dstDir -Force | Out-Null
    }
    Copy-Item $src $dst -Force
}

Remove-Item $tempRoot -Recurse -Force
Remove-Item $tempZip -Force

Write-Host "" 
Write-Host "Phase 1 patch applied." -ForegroundColor Green
Write-Host "data/ and fixtures/ were left untouched." -ForegroundColor Green
Write-Host "" 
Write-Host "Review the patch:" -ForegroundColor Cyan
Write-Host "  git diff --stat"
Write-Host "  git diff"
Write-Host "" 
Write-Host "Then install/test:" -ForegroundColor Cyan
Write-Host "  pip install -r requirements.txt"
Write-Host "  Remove-Item cashbook.db -ErrorAction SilentlyContinue"
Write-Host "  python seed.py data/2020_cashbook.xls"
Write-Host "  python -m unittest discover -s tests -v"
